import { ClockIcon } from 'lucide-vue-next';

const MOBILE_DESCRIPTION = 'Start a work shift to begin tracking your hours for this project.';
const WEB_DESCRIPTION = 'Start a work shift in the mobile app to see your shifts here.';
const ADMIN_MANAGER_DESCRIPTION = "Canvassers' work shifts on this project will appear here.";

interface WorkshiftsGuidedEmptyParams {
  projectId: string;
  isMobile: boolean;
}

export function buildWorkshiftsGuidedEmpty({ projectId, isMobile }: WorkshiftsGuidedEmptyParams): GuidedEmptyConfig {
  const content: GuidedEmptyContent = {
    icon: ClockIcon,
    title: 'No work shifts yet',
    description: isMobile ? MOBILE_DESCRIPTION : WEB_DESCRIPTION,
    actions: [
      { label: 'Start a Work Shift', to: { name: 'shift', query: { project_id: projectId } }, mobileOnly: true },
    ],
  };

  const adminManagerContent: GuidedEmptyContent = {
    icon: ClockIcon,
    title: 'No work shifts yet',
    description: ADMIN_MANAGER_DESCRIPTION,
  };

  return {
    canvasser: content,
    subcontractor_canvasser: content,
    admin: adminManagerContent,
    manager: adminManagerContent,
  };
}
